import numpy as np
def load_xyz(fn):
    lines = open(fn).read().splitlines()
    n = int(lines[0]); els=[]; xyz=[]
    for l in lines[2:2+n]:
        p=l.split(); els.append(p[0]); xyz.append([float(p[1]),float(p[2]),float(p[3])])
    return els, np.array(xyz)
els,xyz = load_xyz('complex_constrained.xyz')
n=len(els)
# find H atoms close to Ru
for i in range(n):
    if els[i]=='H':
        for r in [86,87]:
            d=np.linalg.norm(xyz[i]-xyz[r])
            if d<2.2:
                # find what heavy atom this H is attached to
                att=None
                for j in range(n):
                    if j!=i and els[j]!='H' and np.linalg.norm(xyz[i]-xyz[j])<1.25:
                        att=(els[j],j,round(np.linalg.norm(xyz[i]-xyz[j]),3))
                print(f'H{i} - Ru{r}: {d:.3f}   attached to: {att}')
